WITH parsed AS (SELECT id, created_at, coupon_codes, ship_to, SIZE(items) AS num_items, COALESCE(attributes['device'], 'unknown') AS device_or_default, ARRAY_CONTAINS(coupon_codes, 'SPRING10') AS used_spring10, ship_to.country AS ship_country FROM carts) SELECT id, created_at, ship_country, ROW_NUMBER() OVER (ORDER BY num_items, id) AS row_seq, RANK() OVER (PARTITION BY ship_country ORDER BY num_items DESC NULLS FIRST) AS num_items_rank, SUM(num_items) OVER (PARTITION BY ship_country ORDER BY created_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_num_items FROM parsed;
